//! GPOS pair adjustment, differentially against fontTools.
//!
//! stb never read GPOS, so there is no reference implementation to inherit an
//! answer from -- and the oracle that could have been borrowed is gone. This
//! compares against fontTools' decode of the same tables instead: an
//! independent parse of the same bytes, so a disagreement is a bug on one
//! side rather than a shared assumption.
//!
//! Ground truth is generated by a script that walks fontTools' objects, not by
//! re-reading bytes here, so the two sides never share parsing code.
//!
//! Point GLYFZ_GPOS at a manifest of `fontpath|pairsfile` entries separated by
//! semicolons, or run `zig build gpos -Dpairs=...`. No font is vendored, so the
//! run is reproducible for anyone with fonts rather than pinned to files.

const std = @import("std");
const glyfz = @import("glyfz");

fn readFile(gpa: std.mem.Allocator, path: []const u8) ![]u8 {
    var threaded: std.Io.Threaded = .init(gpa, .{});
    defer threaded.deinit();
    return std.Io.Dir.cwd().readFileAlloc(threaded.io(), path, gpa, .limited(64 * 1024 * 1024));
}

test "pair adjustments agree with fontTools on real faces" {
    const gpa = std.testing.allocator;
    // 0.16 dropped std.posix.getenv; this test links libc for it.
    const manifest_z = std.c.getenv("GLYFZ_GPOS") orelse return error.SkipZigTest;
    const manifest = std.mem.span(manifest_z);

    var faces: usize = 0;
    var compared: usize = 0;
    var nonzero: usize = 0;
    var mismatched: usize = 0;
    var printed: usize = 0;

    var entries = std.mem.splitScalar(u8, manifest, ';');
    while (entries.next()) |entry| {
        if (entry.len == 0) continue;
        const bar = std.mem.indexOfScalar(u8, entry, '|') orelse return error.BadManifest;
        const font_path = entry[0..bar];
        const pairs_path = entry[bar + 1 ..];

        const bytes = try readFile(gpa, font_path);
        defer gpa.free(bytes);
        const pairs = try readFile(gpa, pairs_path);
        defer gpa.free(pairs);

        const font = try glyfz.Font.init(bytes);
        faces += 1;
        try std.testing.expect(font.hasGpos());

        var lines = std.mem.tokenizeScalar(u8, pairs, '\n');
        while (lines.next()) |line| {
            var f = std.mem.tokenizeScalar(u8, line, ' ');
            const l = try std.fmt.parseInt(u16, f.next().?, 10);
            const r = try std.fmt.parseInt(u16, f.next().?, 10);
            const want = try std.fmt.parseInt(i16, f.next().?, 10);
            const got = font.kernGpos(l, r);
            compared += 1;
            if (want != 0) nonzero += 1;
            if (got != want) {
                mismatched += 1;
                if (printed < 10) {
                    printed += 1;
                    std.debug.print("mismatch {s} ({d},{d}) want {d} got {d}\n", .{ font_path, l, r, want, got });
                }
            }
        }
    }

    std.debug.print("gpos: faces {d} pairs {d} nonzero {d} mismatched {d}\n", .{ faces, compared, nonzero, mismatched });

    // A comparison that compared nothing would pass every assertion below.
    try std.testing.expect(faces >= 3);
    try std.testing.expect(compared > 5000);
    try std.testing.expect(nonzero > 500);
    try std.testing.expectEqual(@as(usize, 0), mismatched);
}
